examples.code:
#include <atomic>
#include <iostream>

int main() {
    alignas(std::atomic_ref<int>::required_alignment) int storage{20};
    std::atomic_ref<int> stock{storage};
    std::cout << stock.fetch_add(5) << " -> " << stock.load() << "\n";
    std::cout << stock.fetch_sub(3) << " -> " << stock.load() << "\n";
    stock += 2;
    stock -= 4;
    ++stock;
    --stock;
    std::cout << stock.load() << "\n";
}
